  /// `lines` 값입니다.
  final List<PricingLine> lines;

  /// 적립금 사용(#93 P3). 없으면 쓰지 않습니다 — 결과는 적립금 이전과 같습니다.
  final PricingPoints? points;

  /// `coupons` 값입니다.
  final List<PricingCoupon> coupons;

  /// 배송비 견적. 없으면 배송비 0으로 계산하고 배송비 쿠폰은 할인할 금액이 없습니다.
  final PricingDelivery? delivery;

  /// 이 상점에서 결제 완료 주문이 없는 회원인지입니다.
  final bool firstOrder;

  /// 회원 주문인지입니다.
  final bool isMember;

  /// 사용 기간 판정 시각.
  final DateTime now;

  /// 사용 기간·회원·첫 구매 조건을 다시 보지 않습니다 — **환불 정산의 재계산 전용입니다.** 그 조건은 결제 시작에서
  /// 이미 통과했습니다. 주문 시각(승인 시각)으로 기간을 다시 보면 결제 시작과 승인 사이에 끝난 쿠폰이 조건을 잃은
  /// 것처럼 보이고, 탈퇴한 회원의 반품이 회원 전용 조건에 떨어집니다. 대상과 최소 금액만 봅니다.
  final bool? ignoreEligibility;

  /// 주문 통화의 규칙 값(이슈 #130) — 정률 할인 내림 단위(판매가 단위)와 적립금 사용 뒤 남길 최소 결제액. 생략하면 KRW 규칙입니다.
  /// 금액 입력은 모두 이 통화의 최소 단위입니다.
  final MoneyRules? moneyRules;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {
        'lines': lines,
        if (points != null) 'points': points,
        'coupons': coupons,
        if (delivery != null) 'delivery': delivery,
        'firstOrder': firstOrder,
        'isMember': isMember,
        'now': now,
        if (ignoreEligibility != null) 'ignoreEligibility': ignoreEligibility,
        if (moneyRules != null) 'moneyRules': moneyRules
      };
}

/// 줄 하나에 들어간 쿠폰별 할인.
class CouponAllocation {
  /// [CouponAllocation]을 만듭니다.
  const CouponAllocation({required this.couponKey, required this.amount});

  /// `couponKey` 값입니다.
  final String couponKey;

  /// `amount` 값입니다.
  final int amount;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {'couponKey': couponKey, 'amount': amount};
}

/// PricingLineResult 값입니다.
class PricingLineResult {
  /// [PricingLineResult]을 만듭니다.
  const PricingLineResult(
      {required this.lineId,
      required this.amount,
      required this.couponDiscount,
      required this.allocations,
      required this.pointAllocation});

  /// `lineId` 값입니다.
  final String lineId;

  /// 즉시할인 반영 금액 (쿠폰 전).
  final int amount;

  /// 이 줄에 들어간 쿠폰 할인 합계 — 상품 쿠폰 + 주문 쿠폰 배분.
  final int couponDiscount;

  /// `allocations` 값입니다.
  final List<CouponAllocation> allocations;

  /// 이 줄에 배분한 사용 적립금(#93 P3). 적립금을 쓰지 않으면 0.
  final int pointAllocation;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {
        'lineId': lineId,
        'amount': amount,
        'couponDiscount': couponDiscount,
        'allocations': allocations,
        'pointAllocation': pointAllocation
      };
}

/// PricingCouponResult 값입니다.
class PricingCouponResult {
  /// [PricingCouponResult]을 만듭니다.
  const PricingCouponResult(
      {required this.couponKey,
      required this.couponId,
      required this.kind,
      required this.applied,
      required this.discount,
      required this.rejectReason,
      required this.lineId,
      required this.eligibleLineIds});

  /// `couponKey` 값입니다.
  final String couponKey;

  /// `couponId` 값입니다.
  final String couponId;

  /// `kind` 값입니다.
  final CouponKind kind;

  /// `applied` 값입니다.
  final bool applied;

  /// 이 쿠폰의 할인액. 적용하지 못했으면 0.
  final int discount;

  /// `rejectReason` 값입니다.
  final CouponRejectReason? rejectReason;

  /// 상품 쿠폰이 걸린 줄. 그 밖은 null.
  final String? lineId;

  /// 이 쿠폰의 대상 줄 — 판정에 쓴 순서 그대로입니다. 환불 정산이 주문 시점 대상을 되살리는 데 씁니다.
  final List<String> eligibleLineIds;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {
        'couponKey': couponKey,
        'couponId': couponId,
        'kind': kind,
        'applied': applied,
        'discount': discount,
        'rejectReason': rejectReason,
        'lineId': lineId,
        'eligibleLineIds': eligibleLineIds
      };
}

/// PricingBundleResult 값입니다.
class PricingBundleResult {
  /// [PricingBundleResult]을 만듭니다.
  const PricingBundleResult({required this.bundleKey, required this.couponDiscount, required this.pointAllocation});

  /// `bundleKey` 값입니다.
  final String bundleKey;

  /// `couponDiscount` 값입니다.
  final int couponDiscount;

  /// 이 배송 묶음에 배분한 사용 적립금(#93 P3).
  final int pointAllocation;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() =>
      {'bundleKey': bundleKey, 'couponDiscount': couponDiscount, 'pointAllocation': pointAllocation};
}

/// PricingResult 값입니다.
class PricingResult {
  /// [PricingResult]을 만듭니다.
  const PricingResult(
      {required this.lines,
      required this.coupons,
      required this.bundles,
      required this.productAmount,
      required this.couponDiscountAmount,
      required this.deliveryFee,
      required this.deliveryDiscountAmount,
      required this.pointAmount,
      required this.pointMaxUsable,
      required this.pointAdjustReason,
      required this.pointRejectReason,
      required this.totalAmount});

  /// `lines` 값입니다.
  final List<PricingLineResult> lines;

  /// `coupons` 값입니다.
  final List<PricingCouponResult> coupons;

  /// 배송비 쿠폰의 묶음별 배분.
  final List<PricingBundleResult> bundles;

  /// 상품 금액 합 (즉시할인 반영, 쿠폰 전).
  final int productAmount;

  /// 상품·주문 쿠폰 할인 합계.
  final int couponDiscountAmount;

  /// 배송비 (쿠폰 전).
  final int deliveryFee;

  /// 배송비 쿠폰 할인.
  final int deliveryDiscountAmount;

  /// 사용 적립금(#93 P3). 쓰지 않으면 0.
  final int pointAmount;

  /// 지금 쓸 수 있는 최대 적립금 — 주문서 안내값(잔액을 모두 요청했을 때의 금액). 적립금 입력이 없으면 0.
  final int pointMaxUsable;

  /// 요청보다 적게 썼다면 그 이유 — `MIN_PAYMENT`: 남는 결제 금액이 1~99원이라 100원을 남기려고 줄였습니다(전액이면 0원 결제).
  final String? pointAdjustReason;

  /// 요청했지만 쓰지 못했다면 그 이유.
  final PointRejectReason? pointRejectReason;

  /// 결제 금액 = productAmount − couponDiscountAmount + deliveryFee − deliveryDiscountAmount − pointAmount.
  final int totalAmount;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {
        'lines': lines,
        'coupons': coupons,
        'bundles': bundles,
        'productAmount': productAmount,
        'couponDiscountAmount': couponDiscountAmount,
        'deliveryFee': deliveryFee,
        'deliveryDiscountAmount': deliveryDiscountAmount,
        'pointAmount': pointAmount,
        'pointMaxUsable': pointMaxUsable,
        'pointAdjustReason': pointAdjustReason,
        'pointRejectReason': pointRejectReason,
        'totalAmount': totalAmount
      };
}

/// 주문이 받은 쿠폰 한 장 — 주문 시점 규칙과 대상 줄을 굳힌 값입니다(`orders.discounts`의 항목).
/// 환불 정산은 이 값만 읽습니다. 셀러가 쿠폰을 바꾸거나 상품의 카테고리가 바뀌어도 결과가 같습니다.
class AppliedCouponSnapshot {
  /// [AppliedCouponSnapshot]을 만듭니다.
  const AppliedCouponSnapshot(
      {required this.couponKey,
      required this.rule,
      required this.lineId,
      required this.eligibleLineIds,
      required this.discount});

  /// `couponKey` 값입니다.
  final String couponKey;

  /// `rule` 값입니다.
  final CouponRule rule;

  /// 상품 쿠폰이 걸린 주문상품 id. 그 밖은 null.
  final String? lineId;

  /// 주문 시점 대상 주문상품 id — 주문서 항목 순서 그대로입니다.
  final List<String> eligibleLineIds;

  /// 주문 시점 할인액.
  final int discount;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {
        'couponKey': couponKey,
        'rule': rule,
        'lineId': lineId,
        'eligibleLineIds': eligibleLineIds,
        'discount': discount
      };
}

/// 정산이 보는 주문상품 한 줄 — 이번 취소를 **반영한 뒤**의 활성 수량입니다.
class CouponSettlementLine {
  /// [CouponSettlementLine]을 만듭니다.
  const CouponSettlementLine(
      {required this.lineId,
      required this.productId,
      required this.quantity,
      required this.activeQuantity,
      required this.totalPrice,
      required this.allocations});

  /// `lineId` 값입니다.
  final String lineId;

  /// `productId` 값입니다.
  final String productId;

  /// `quantity` 값입니다.
  final int quantity;

  /// 남은 활성 수량 (이번 취소 반영 뒤).
  final int activeQuantity;

  /// 주문상품 금액 (즉시할인 반영 단가 × 전체 수량, 쿠폰 전).
  final int totalPrice;

  /// 주문 시점 쿠폰별 배분.
  final List<CouponAllocation> allocations;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {
        'lineId': lineId,
        'productId': productId,
        'quantity': quantity,
        'activeQuantity': activeQuantity,
        'totalPrice': totalPrice,
        'allocations': allocations
      };
}

/// 쿠폰 한 장의 정산 누적 — `orders.coupon_settlements[couponKey]`.
class CouponSettlementState {
  /// [CouponSettlementState]을 만듭니다.
  const CouponSettlementState({required this.charged, required this.waived});

  /// 지금까지 환불에서 뺀 조건 미달 차감 (되돌린 금액을 뺀 값).
  final int charged;

  /// 판매자 귀책·정책 꺼짐으로 받지 않기로 한 미달분 — 뒤의 환불이 다시 청구하지 않게 남깁니다.
  final int waived;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {'charged': charged, 'waived': waived};
}

/// CouponSettlementInput 값입니다.
class CouponSettlementInput {
  /// [CouponSettlementInput]을 만듭니다.
  const CouponSettlementInput(
      {required this.coupons,
      required this.lines,
      required this.settlements,
      required this.shortfallCharge,
      required this.sellerFault,
      required this.chargeableAmount});

  /// `coupons` 값입니다.
  final List<AppliedCouponSnapshot> coupons;

  /// `lines` 값입니다.
  final List<CouponSettlementLine> lines;

  /// `settlements` 값입니다.
  final Map<String, ({int? charged, int? waived})?> settlements;

  /// 상점 환불 정책 `couponShortfallCharge`.
  final bool shortfallCharge;

  /// 판매자 귀책(직권취소, 불량·오배송 반품) — 미달분을 청구하지 않습니다.
  final bool sellerFault;

  /// 이번 환불에서 실제로 뺄 수 있는 금액 — 차감의 상한입니다. 넘겨 차감하면 환불은 0원으로 잘리는데 기록에는
  /// 전액이 남아, 뒤에 되돌릴 때 받지 않은 돈을 돌려줍니다(배송비 미달 차감의 `chargeableAmount`와 같은 이유).
  final int chargeableAmount;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {
        'coupons': coupons,
        'lines': lines,
        'settlements': settlements,
        'shortfallCharge': shortfallCharge,
        'sellerFault': sellerFault,
        'chargeableAmount': chargeableAmount
      };
}

/// CouponSettlementEntry 값입니다.
class CouponSettlementEntry {
  /// [CouponSettlementEntry]을 만듭니다.
  const CouponSettlementEntry(
      {required this.couponKey,
      required this.allocatedRemaining,
      required this.recomputed,
      required this.target,
      required this.charge,
      required this.refund,
      required this.waive,
      required this.next});

  /// `couponKey` 값입니다.
  final String couponKey;

  /// 남은 주문상품에 배분된 할인.
  final int allocatedRemaining;

  /// 남은 주문상품으로 다시 계산한 할인 — 쿠폰 조건을 잃었으면 0.
  final int recomputed;

  /// 누적 미달분 목표 = 조건을 잃었으면 `allocatedRemaining`, 아니면 0.
  final int target;

  /// `charge` 값입니다.
  final int charge;

  /// `refund` 값입니다.
  final int refund;

  /// `waive` 값입니다.
  final int waive;

  /// `next` 값입니다.
  final CouponSettlementState next;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {
        'couponKey': couponKey,
        'allocatedRemaining': allocatedRemaining,
        'recomputed': recomputed,
        'target': target,
        'charge': charge,
        'refund': refund,
        'waive': waive,
        'next': next
      };
}

/// CouponSettlementResult 값입니다.
class CouponSettlementResult {
  /// [CouponSettlementResult]을 만듭니다.
  const CouponSettlementResult({required this.chargeAmount, required this.refundAmount, required this.entries});

  /// 이번 환불에서 뺄 금액 — 조건 미달 차감.
  final int chargeAmount;

  /// 이번 환불에 더할 금액 — 앞선 환불에서 뺀 차감을 되돌린 몫.
  final int refundAmount;

  /// `entries` 값입니다.
  final List<CouponSettlementEntry> entries;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {'chargeAmount': chargeAmount, 'refundAmount': refundAmount, 'entries': entries};
}

/// NO_COUPON_SETTLEMENT 값입니다.
const NO_COUPON_SETTLEMENT = <String, Object?>{'chargeAmount': 0, 'refundAmount': 0, 'entries': <Object?>[]};
